    export type RefreshDataMutationResult = NonNullable<Awaited<ReturnType<typeof refreshData>>>

    export type RefreshDataMutationError = ErrorType<unknown>

    /**
 * @summary Refresh cached data
 */
export const useRefreshData = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof refreshData>>, TError,void, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof refreshData>>,
        TError,
        void,
        TContext
      > => {
      return useMutation(getRefreshDataMutationOptions(options));
    }

